#include <cstdio>
#include <cstddef>

struct Tick { double bid; double ask; };   // 16 bytes

template <std::size_t N>                   // N must be a power of two
class Ring {
    static_assert((N & (N - 1)) == 0, "N must be a power of two");
    Tick slots[N]{};
    std::size_t head = 0;   // written only by the producer
    std::size_t tail = 0;   // written only by the consumer
public:
    bool push(const Tick& t) {
        if (head - tail == N) return false;       // full
        slots[head & (N - 1)] = t;                // wrap via mask
        ++head;
        return true;
    }
    bool pop(Tick& out) {
        if (tail == head) return false;           // empty
        out = slots[tail & (N - 1)];
        ++tail;
        return true;
    }
};

int main() {
    Ring<1024> ring;                              // allocated once, never grows
    for (int i = 0; i < 1000; ++i)
        ring.push({i, i + 0.5});
    Tick t;
    ring.pop(t);
    std::printf("%.1f\n", t.bid);                 // 0.0
    return 0;
}
